input.command:
bun -e "
const apiKey = process.env.OPENROUTER_API_KEY;
const res = await fetch('https://openrouter.ai/api/v1/auth/key', {
  headers: { Authorization: 'Bearer ' + apiKey }
});
console.log('Status:', res.status);
const data = await res.json();
console.log('Auth:', JSON.stringify(data).substring(0, 200));
"

unset OPENROUTER_API_KEY && bun -e "
const apiKey = process.env.OPENROUTER_API_KEY;
console.log('Key prefix:', apiKey?.substring(0, 15));
const res = await fetch('https://openrouter.ai/api/v1/auth/key', {
  headers: { Authorization: 'Bearer ' + apiKey }
});
console.log('Status:', res.status);
const data = await res.json();
console.log('Auth:', JSON.stringify(data).substring(0, 300));
"

unset OPENROUTER_API_KEY && bun -e "
const apiKey = process.env.OPENROUTER_API_KEY;
console.log('Key:', apiKey?.substring(0, 15));
const res = await fetch('https://openrouter.ai/api/v1/chat/completions', {
  method: 'POST',
  headers: { 
    Authorization: 'Bearer ' + apiKey,
    'Content-Type': 'application/json'
  },
  body: JSON.stringify({
    model: 'nvidia/nemotron-nano-9b-v2',
    messages: [{ role: 'user', content: 'Say hello' }],
    max_tokens: 10
  })
});
console.log('Status:', res.status);
const t = await res.text();
console.log(t.substring(0, 300));
"

unset OPENROUTER_API_KEY && bun -e "
const { ChatOpenAI } = require('@langchain/openai');
const apiKey = process.env.OPENROUTER_API_KEY;
console.log('ENV key:', apiKey?.substring(0, 15));
const model = new ChatOpenAI({
  model: 'nvidia/nemotron-nano-9b-v2',
  apiKey: apiKey,
  configuration: {
    baseURL: 'https://openrouter.ai/api/v1',
    defaultHeaders: {
      'HTTP-Referer': 'https://github.com/anomalyco/bballgenius',
      'X-Title': 'BBallGenius Chatbot',
    },
  },
  temperature: 0,
  timeout: 30_000,
});
try {
  const result = await model.invoke([{ role: 'user', content: 'Say hello in 3 words' }]);
  console.log('SUCCESS:', result.content.substring(0, 100));
} catch (e) {
  console.log('ERROR:', e.message?.substring(0, 200));
}
"

