 type ExpectedKind = 'contains' | 'numeric_contains' | 'clarification' | 'not_available';

 type FailureCategory =
   | 'pass'
   | 'sql_syntax'
   | 'sql_schema'
   | 'tool_loop'
   | 'duplicate_final_answer'
   | 'hallucination'
   | 'wrong_answer'
   | 'refused'
   | 'no_clarification'
   | 'not_available_expected'
   | 'timeout'
   | 'crash'
   | 'recursion_limit'
   | 'missing_final_answer'
   | 'evaluator_error'
   | 'unknown';

 interface Question {
   id: string;
   q: string;
   expected: string;
   expectedKind: ExpectedKind;
   tier: string;
 }

 interface ToolTrace {
   index: number;
   name: string;
   input?: unknown;
   inputSummary?: string;
   outputSummary?: string;
   error?: string;
   sqlCandidates: string[];
   startedAt: string;
   endedAt?: string;
   latencyMs?: number;
 }

 interface RunTrace {
   runId: string;
   threadId: string;
   questionId: string;
   question: string;
   expected: string;
   expectedKind: ExpectedKind;
   tier: string;
   model: string;
   modelParams: Record<string, unknown>;
   graph: {
     recursionLimit?: number | null;
     maxToolCalls: number;
   };
   timing: {
     startedAt: string;
     endedAt?: string;
     latencyMs?: number;
     runTimeoutMs: number;
     totalTimeoutMs: number;
   };
   nodeTransitions: string[];
   stateKeysChanged: string[];
   messagesSeenAtDone: number | null;
   toolCalls: ToolTrace[];
   sql: {
     generated: string[];
     validationResults: string[];
     executionResultSummaries: string[];
     executionLatenciesMs: number[];
   };
   streamedTokenText: string;
   finalAnswerCandidate: string;
   finalAnswerEmitted: string;
   evaluator: {
     passed: boolean;
     verdict: string;
     failureCategory: FailureCategory;
     duplicateFinalAnswer: boolean;
     duplicateEvidence?: string;
     normalizedExpected: string;
     normalizedActual: string;
   };
   stop: {
     reason: string;
     recursionLimitHit: boolean;
     timeout: boolean;
     error?: string;
   };
