const { DuckDBInstance } = require('@duckdb/node-api');
(async () => {
  const inst = await DuckDBInstance.fromCache('data/nba.duckdb');
  const conn = await inst.connect();
  const q = async (sql) => { const r = await conn.runAndReadAll(sql); return r.getRowObjectsJson(); };

  // Jordan playoff advanced - check if there are any playoff rows at all
