  // Jordan regular season PER 1995
  console.log('JORDAN_REG_1995:', JSON.stringify(await q(\"SELECT player_name, per, season_end_year, is_playoffs FROM main.fact_bref_player_season_advanced WHERE player_name = 'Michael Jordan' AND season_end_year = 1995\")));

