  console.log('AST_TOP5:', JSON.stringify(await q(\"SELECT player_name, SUM(ast) as total_ast FROM main.fact_bref_player_season_totals WHERE is_playoffs = false AND team NOT LIKE '%TM%' GROUP BY player_name ORDER BY total_ast DESC LIMIT 5\")));

  // Steals leaders
  console.log('STL_TOP5:', JSON.stringify(await q(\"SELECT player_name, SUM(stl) as total_stl FROM main.fact_bref_player_season_totals WHERE is_playoffs = false AND team NOT LIKE '%TM%' GROUP BY player_name ORDER BY total_stl DESC LIMIT 5\")));

  // Rebound leaders  
  console.log('TRB_TOP5:', JSON.stringify(await q(\"SELECT player_name, SUM(trb) as total_trb FROM main.fact_bref_player_season_totals WHERE is_playoffs = false AND team NOT LIKE '%TM%' GROUP BY player_name ORDER BY total_trb DESC LIMIT 5\")));

  // Blocks leaders
  console.log('BLK_TOP5:', JSON.stringify(await q(\"SELECT player_name, SUM(blk) as total_blk FROM main.fact_bref_player_season_totals WHERE is_playoffs = false AND team NOT LIKE '%TM%' GROUP BY player_name ORDER BY total_blk DESC LIMIT 5\")));

  // 3PM leaders
  console.log('X3P_TOP5:', JSON.stringify(await q(\"SELECT player_name, SUM(x3p) as total_3pm FROM main.fact_bref_player_season_totals WHERE is_playoffs = false AND team NOT LIKE '%TM%' GROUP BY player_name ORDER BY total_3pm DESC LIMIT 5\")));

  // MVP count by player
  console.log('MVP_COUNT:', JSON.stringify(await q(\"SELECT player_name, COUNT(*) as mvps FROM main.fact_player_award_vote WHERE winner = true AND lower(award) = 'nba mvp' GROUP BY player_name ORDER BY mvps DESC LIMIT 10\")));

  // ROY winners recent
  console.log('ROY:', JSON.stringify(await q(\"SELECT player_name, season_end_year FROM main.fact_player_award_vote WHERE winner = true AND lower(award) = 'nba roy' ORDER BY season_end_year DESC LIMIT 5\")));

  // DPOY
  console.log('DPOY:', JSON.stringify(await q(\"SELECT player_name, season_end_year FROM main.fact_player_award_vote WHERE winner = true AND lower(award) = 'nba dpoy' ORDER BY season_end_year DESC LIMIT 5\")));

  // LeBron career assists
  console.log('LEBRON_AST:', JSON.stringify(await q(\"SELECT SUM(ast) as total FROM main.fact_bref_player_season_totals WHERE player_name = 'LeBron James' AND is_playoffs = false AND team NOT LIKE '%TM%'\")));

  // Kareem career points regular season
  console.log('KAREEM_PTS:', JSON.stringify(await q(\"SELECT SUM(pts) as total FROM main.fact_bref_player_season_totals WHERE player_name = 'Kareem Abdul-Jabbar' AND is_playoffs = false AND team NOT LIKE '%TM%'\")));

  // Wilt career rebounds
  console.log('WILT_TRB:', JSON.stringify(await q(\"SELECT SUM(trb) as total FROM main.fact_bref_player_season_totals WHERE player_name = 'Wilt Chamberlain' AND is_playoffs = false AND team NOT LIKE '%TM%'\")));

  // Playoff points leader from DB
  console.log('PLAYOFF_PTS_TOP5:', JSON.stringify(await q(\"SELECT player_name, SUM(pts) as total FROM main.fact_bref_player_season_totals WHERE is_playoffs = true AND team NOT LIKE '%TM%' GROUP BY player_name ORDER BY total DESC LIMIT 5\")));

  // Games played
  console.log('GP_TOP5:', JSON.stringify(await q(\"SELECT player_name, SUM(g) as total_games FROM main.fact_bref_player_season_totals WHERE is_playoffs = false AND team NOT LIKE '%TM%' GROUP BY player_name ORDER BY total_games DESC LIMIT 5\")));

  conn.disconnectSync();
})();
