import { DuckDBInstance } from '@duckdb/node-api';
import { resolveDbPath } from '../src/shared/dbPath.js';

const dbPath = resolveDbPath();
console.log('DB path:', dbPath);
const instance = await DuckDBInstance.fromCache(dbPath);
const conn = await instance.connect();

async function q(label, sql) {
  const r = await conn.runAndReadAll(sql);
  const rows = r.getRows();
  console.log(`\n=== ${label} ===`);
  for (const row of rows) console.log(...row);
}

await q('REBOUND LEADER (fact_bref, is_playoffs=false)',
  "SELECT player_name, SUM(trb) as total FROM main.fact_bref_player_season_totals WHERE team NOT LIKE '%TM%' AND is_playoffs = false GROUP BY player_name ORDER BY total DESC LIMIT 5");

await q('REBOUND LEADER (stg_bref.player_totals)',
  "SELECT player_name, SUM(trb) as total FROM stg_bref.player_totals WHERE team NOT LIKE '%TM%' GROUP BY player_name ORDER BY total DESC LIMIT 5");

await q('LEBRON ASSISTS (fact_bref)',
  "SELECT SUM(ast) as total FROM main.fact_bref_player_season_totals WHERE player_name = 'LeBron James' AND team NOT LIKE '%TM%' AND is_playoffs = false");

await q('LEBRON ASSISTS (stg_bref)',
  "SELECT SUM(ast) as total FROM stg_bref.player_totals WHERE player_name = 'LeBron James' AND team NOT LIKE '%TM%'");

await q('LEBRON ASSISTS (game_stats)',
  "SELECT SUM(assists) as total FROM main.fact_player_game_stats WHERE person_id IN (SELECT person_id FROM main.dim_player WHERE first_name = 'LeBron' AND last_name = 'James')");

await q('OLAJUWON BLOCKS (fact_bref)',
  "SELECT SUM(blk) as total FROM main.fact_bref_player_season_totals WHERE player_name LIKE '%Olajuwon%' AND team NOT LIKE '%TM%' AND is_playoffs = false");

await q('OLAJUWON BLOCKS (stg_bref)',
  "SELECT SUM(blk) as total FROM stg_bref.player_totals WHERE player_name LIKE '%Olajuwon%' AND team NOT LIKE '%TM%'");

await q('KAREEM PTS (fact_bref)',
  "SELECT SUM(pts) as total FROM main.fact_bref_player_season_totals WHERE player_name LIKE '%Kareem%' AND team NOT LIKE '%TM%' AND is_playoffs = false");

await q('KAREEM FG (fact_bref)',
  "SELECT SUM(fg) as total FROM main.fact_bref_player_season_totals WHERE player_name LIKE '%Kareem%' AND team NOT LIKE '%TM%' AND is_playoffs = false");

await q('ROY 2003-04 (award vote)',
  "SELECT player_name, award, season_end_year, winner FROM main.fact_player_award_vote WHERE lower(award) LIKE '%roy%' AND season_end_year = 2004 LIMIT 5");

await q('ROY 2003-04 (honor)',
  "SELECT player_name, honor, season_end_year FROM main.fact_player_honor WHERE lower(honor) LIKE '%rook%' AND season_end_year = 2004 LIMIT 5");

await q('AWARD NAMES for LeBron 2004',
  "SELECT DISTINCT award FROM main.fact_player_award_vote WHERE player_name LIKE '%LeBron%' AND season_end_year = 2004");

await q('3+ MVP WINS',
  "SELECT player_name, COUNT(*) as wins FROM main.fact_player_award_vote WHERE lower(award) = 'nba mvp' AND winner = true GROUP BY player_name HAVING COUNT(*) >= 3 ORDER BY wins DESC");

await q('TIM DUNCAN REBOUNDS (fact_bref)',
  "SELECT SUM(trb) as total FROM main.fact_bref_player_season_totals WHERE player_name LIKE '%Duncan%' AND team NOT LIKE '%TM%' AND is_playoffs = false");

await q('TIM DUNCAN REBOUNDS (stg_bref)',
  "SELECT SUM(trb) as total FROM stg_bref.player_totals WHERE player_name LIKE '%Duncan%' AND team NOT LIKE '%TM%'");

await q('STOCKTON ASSISTS (fact_bref)',
  "SELECT SUM(ast) as total FROM main.fact_bref_player_season_totals WHERE player_name LIKE '%Stockton%' AND team NOT LIKE '%TM%' AND is_playoffs = false");

await conn.close();
await instance.close();

