import type { BaseMessage } from '@langchain/core/messages';
import { getModel } from '../openrouter.js';
import { getChatbotGraph } from './graph.js';
import type { ChatbotStateType } from './state.js';

export interface TokenUsage {
  inputTokens: number;
  outputTokens: number;
}

export type ChainStageName =
  | 'classify_intent'
  | 'inject_schema'
  | 'llm'
  | 'tools'
  | 'sql_critic'
  | 'validate_answer';

export type StreamEvent =
  | { type: 'token'; content: string }

  input: BaseMessage[],
  threadId: string,
): AsyncGenerator<StreamEvent, void, undefined> {
  const graph = getChatbotGraph();
  const config = {
    configurable: { thread_id: threadId },
    metadata: { app: 'bballgenius-chatbot', model: getModel() },
  };

  try {
    const stream = await graph.streamEvents(
      { messages: input },
      {
        version: 'v2',
        configurable: { thread_id: threadId },
        metadata: config.metadata,
        recursionLimit: 25,
      },
    );

